import TaskCard from "./TaskCard";

export interface Task {
  id: string | number;
  title: string;
  description: string;
  priority: string;
  completed: boolean;
  category: string;
  tags: string[];
  dueDate?: string | number;
}

interface TaskListProps {
  tasks?: Task[];
  countText?: string;
  onToggle?: (id: string | number) => void;
  onDelete?: (id: string | number) => void;
  linkToTaskDetail?: boolean;

  onUpdateTask?: (
    id: string | number,
    updates: {
      title: string;
      description: string;
      priority: string;
      dueDate?: string | number;
    }
  ) => void;

  editingId?: string | number | null;
  setEditingId?: (
    id: string | number | null
  ) => void;
}

const HARDCODED_TASKS: Task[] = [
  {
    id: 1,
    title: "Task One",
    description: "First hardcoded task",
    priority: "High",
    completed: false,
    category: "General",
    tags: [],
  },
  {
    id: 2,
    title: "Task Two",
    description: "Second hardcoded task",
    priority: "Medium",
    completed: false,
    category: "Work",
    tags: [],
  },
  {
    id: 3,
    title: "Task Three",
    description: "Third hardcoded task",
    priority: "Low",
    completed: false,
    category: "Personal",
    tags: [],
  },
];

export default function TaskList({
  tasks = HARDCODED_TASKS,
  countText,
  onToggle,
  onDelete,
  onUpdateTask,
  editingId,
  setEditingId,
}: TaskListProps) {
  return (
    <>
      {countText && (
        <div id="task-count">
          {countText}
        </div>
      )}

      <section id="task-list">
        {tasks.map((task) => (
          <TaskCard
            key={task.id}
            id={task.id}
            title={task.title}
            description={task.description}
            priority={task.priority}
            completed={task.completed}
            category={task.category}
            tags={task.tags}
            dueDate={task.dueDate}
            onToggle={onToggle}
            onDelete={onDelete}
          />
        ))}
      </section>
    </>
  );
}
